def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    # Iterate backwards: later carpets are on top of earlier ones.
    for i in range(n - 1, -1, -1):
        a, b, g, k = carpets[i]
        if a <= x <= a + g and b <= y <= b + k:
            return i + 1   # carpets are numbered starting from 1
    return -1

def polynomial_to_string(n, coeffs):
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (list of int): Coefficients starting with the highest degree term.

    Returns:
        str: The formatted polynomial string.
    """
    terms = []
    first_term = True
    for i, c in enumerate(coeffs):
        if c == 0:
            continue
        degree = n - i
        sign = ''
        abs_c = abs(c)
        if first_term:
            if c < 0:
                sign = '-'
        else:
            sign = '+' if c > 0 else '-'
        # Build coefficient part
        if abs_c == 1 and degree != 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_c)
        # Build variable part
        if degree == 0:
            var_part = ''
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = f'x^{degree}'
        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)
        first_term = False
    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    Parameters:
    encoded (str): The encoded representation.
    original (str): The corresponding original representation.
    message (str): The encrypted message to decode.

    Returns:
    str: Decoded message or "Failed" if decoding is impossible.
    """
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    # Build mapping from encoded -> original
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"
        else:
            mapping[e_char] = o_char

    # Decode message
    decoded_chars = []
    for m_char in message:
        if m_char not in mapping:
            return "Failed"
        decoded_chars.append(mapping[m_char])

    return "".join(decoded_chars)

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that
    P and Q have GCD x0 and LCM y0.

    For such a pair, write P = x0 * a and Q = x0 * b, where a, b are
    positive integers, gcd(a, b) = 1 and a * b = y0 / x0.

    The function iterates over all factor pairs (a, b) of y0 // x0,
    verifies coprimality, and counts ordered pairs accordingly.
    """
    if x0 <= 0 or y0 <= 0 or y0 % x0 != 0:
        return 0

    m = y0 // x0

    def gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    i = 1
    while i * i <= m:
        if m % i == 0:
            a, b = i, m // i
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        i += 1
    return count

def string_transformation(A: str, B: str, rules: list):
    """
    Perform string transformation from A to B using the given rules within at most 10 steps.
    Returns the minimum number of steps required, or "NO ANSWER!" if impossible within 10 steps.
    """
    from collections import deque

    if A == B:
        return 0

    max_steps = 10
    visited = {A}
    queue = deque([(A, 0)])

    while queue:
        current, steps = queue.popleft()
        if steps >= max_steps:
            continue

        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str not in visited:
                    if new_str == B:
                        return steps + 1
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # move past this index to find next occurrence

    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
    - n (int): The original integer number to transform.
    - rules (list of tuples): A list of transformation rules, where each rule is represented
                              as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
    - int: The total count of unique numbers that can be generated.
    """
    # Map each digit to a list of possible transformed digits
    transform_map = {}
    for x, y in rules:
        key = str(x)
        val = str(y)
        if key in transform_map:
            transform_map[key].append(val)
        else:
            transform_map[key] = [val]

    start_str = str(n)
    visited = {int(start_str)}
    queue = [start_str]

    while queue:
        current = queue.pop(0)
        for idx, ch in enumerate(current):
            if ch in transform_map:
                for t in transform_map[ch]:
                    new_num_str = current[:idx] + t + current[idx+1:]
                    new_num = int(new_num_str)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num_str)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    # Helper to normalize names (case‑insensitive comparison)
    def norm(name: str) -> str:
        return name.strip().upper()

    scenario_name = norm(scenario)

    # Pre‑lower the days of week for quick lookup
    days_lower = {day.lower() for day in days_of_week}

    for speaker, stmts in statements.items():
        speaker_norm = norm(speaker)
        for st in stmts:
            # Ignore empty statements
            if not st:
                continue
            st_clean = st.strip()

            # Skip statements containing any day of the week
            if any(day in st_clean.lower() for day in days_lower):
                continue

            # Standardise punctuation for splitting
            parts = [w.strip('.,!?;:') for w in st_clean.split()]
            if not parts:
                continue

            # Determine if the statement is a guilt claim
            is_true = None
            # Pattern: "I am guilty" / "I am not guilty"
            if parts[:3] == ["i", "am", "guilty"]:
                target = speaker_norm
                is_true = (scenario_name == target)
            elif parts[:4] == ["i", "am", "not", "guilty"]:
                target = speaker_norm
                is_true = (scenario_name != target)
            else:
                # Patterns with a name before 'is'
                if "is" in parts:
                    idx = parts.index("is")
                    target_raw = ' '.join(parts[:idx])
                    target = norm(target_raw)
                    after_is = parts[idx + 1:]

                    if after_is and after_is[0] == "guilty":
                        is_true = (scenario_name == target)
                    elif after_is and after_is[:2] == ["not", "guilty"]:
                        is_true = (scenario_name != target)

            # If the statement does not concern guilt, ignore it
            if is_true is None:
                continue

            # Evaluate consistency based on whether the speaker is a liar
            speaker_is_liar = speaker_norm in {norm(n) for n in liar_count}

            if speaker_is_liar:
                # Liar should make a false statement
                if is_true:
                    return False
            else:
                # Truthful speaker should make a true statement
                if not is_true:
                    return False

    return True

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non‑negative")
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        total = 0
        for j in range(i):
            total += dp[j] * dp[i - 1 - j]
        dp[i] = total
    return dp[n]

