def calculate_arrangements(n, m, a):
    MOD = 1000007
    dp = [0] * (m + 1)
    dp[0] = 1
    for idx in range(n):
        limit = a[idx]
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for j in range(1, m + 1):
            prefix[j] = (prefix[j - 1] + dp[j]) % MOD
        new_dp = [0] * (m + 1)
        for j in range(m + 1):
            low = j - limit
            if low > 0:
                val = (prefix[j] - prefix[low - 1]) % MOD
            else:
                val = prefix[j] % MOD
            new_dp[j] = val
        dp = new_dp
    return dp[m] % MOD

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    :param heights: List[int] – a list of student heights.
    :return: int – the minimum number of students that need to leave.
    """
    n = len(heights)
    if n <= 2:
        return 0

    # Longest strictly increasing subsequence ending at each index
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # Longest strictly decreasing subsequence starting at each index
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # Maximize total length of increasing then decreasing part, subtracting 1 for overlap
    max_len = 0
    for i in range(n):
        if inc[i] > 1 and dec[i] > 1:  # peak must have both sides
            max_len = max(max_len, inc[i] + dec[i] - 1)

    # If no valid peak found, the best we can do is a single peak, length 1
    if max_len == 0:
        max_len = 1

    return n - max_len
